mapper.select:
SELECT v.vid, v.uid, v.title, v.cover_url, v.duration, vs.play_times, vs.comment_times, v.created_at FROM video v INNER JOIN video_status vs ON vs.vid = v.vid WHERE v.status = 1 AND v.visibility = 0 AND v.deleted_at IS NULL
AND ( v.created_at < #{cursorCreatedAt} OR ( v.created_at = #{cursorCreatedAt} AND v.vid < #{cursorVid} ) )
ORDER BY v.created_at DESC, v.vid DESC LIMIT #{size}
